{"kind":"tool","id":"ltLo5jC2u7s","toolName":"write_file","input":{"path":"lib/auth/session.ts","instructions":"Fix session resolution: match compact cookie-cache strategy and add database fallback after cache expiry","content":"import "server-only";

import { headers } from "next/headers";
import { redirect } from "next/navigation";

import { getCookieCache } from "better-auth/cookies";

import { auth } from "@/lib/auth";
import type { UserRole } from "@/lib/auth/permissions";

// Strategy must match the server's session.cookieCache strategy. The server
// config (lib/auth/index.ts) enables cookieCache without a `strategy`, so it
// encodes the session_data cookie with better-auth's default "compact"
// strategy (base64url JSON + HMAC). Reading it with the "jwt" strategy fails
// verification and the session reads back as null.
const cookieCacheConfig = { secret: process.env.BETTER_AUTH_SECRET } as const;

type BaseUser = {
  id: string;
  name: string;
  email: string;
  username?: string | null;
  role?: string;
  subscription?: string;
  banned?: boolean;
  banReason?: string | null;
  [key: string]: unknown;
};

type SessionPayload = {
  id: string;
  token: string;
  expiresAt: Date;
  userId: string;
  [key: string]: unknown;
};

export type UserSession = {
  user: {
    id: string;
    name: string;
    email: string;
    username: string | null;
    role: UserRole;
    subscription: string;
    banned: boolean;
    banReason: string | null;
  };
  session: SessionPayload;
};

function asRole(value: unknown): UserRole {
  return (typeof value === "string" ? value : "student") as UserRole;
}

function mapSession(user: BaseUser, session: SessionPayload): UserSession | null {
  // Banned users are treated as unauthenticated.
  if (user.banned) return null;

  return {
    user: {
      id: user.id,
      name: user.name,
      email: user.email,
      username: user.username ?? null,
      role: asRole(user.role ?? "student"),
      subscription: user.subscription ?? "free",
      banned: false,
      banReason: user.banReason ?? null,
    },
    session,
  };
}

/**
 * Resolves the current session from the request cookies.
 *
 * Reads the short-lived cookie cache first (no database round-trip on the hot
 * path), then falls back to the real session in the database. The fallback
 * matters because the cookie cache expires after its 5-minute maxAge while the
 * session cookie itself stays valid for the full session lifetime — without it
 * every user would be silently signed out five minutes after sign-in/sign-out-
 * refresh.
 */
export async function getSession() {
  const headersList = await headers();

  const cached = (await getCookieCache(headersList, cookieCacheConfig)) as {
    session: SessionPayload;
    user: BaseUser;
  } | null;

  const fromCache = cached?.user ? mapSession(cached.user, cached.session) : null;
  if (fromCache) return fromCache;

  // Cookie cache is missing or expired; verify the real session cookie once.
  const dbSession = await auth.api.getSession({ headers: headersList });
  if (!dbSession?.user) return null;

  return mapSession(
    dbSession.user as BaseUser,
    dbSession.session as SessionPayload,
  );
}

/**
 * Layout-level authorization: gate inside each dashboard layout so a role
 * can never reach another role's pages, even if the proxy missed (docs:
 * "handle auth checks in each page/route").
 */
export async function requireRole(allowed: readonly UserRole[]): Promise<{ user: UserSession["user"] }> {
  const session = await getSession();
  if (!session) redirect("/redirect");
  if (!(allowed as readonly string[]).includes(session.user.role)) redirect("/redirect");
  return { user: session.user };
}

/** Maps a user role to its dashboard home path. */
export function roleHome(role: UserRole): string {
  switch (role) {
    case "super-admin":
    case "admin":
      return "/admin/dashboard";
    case "tutor":
      return "/tutors/dashboard";
    case "student":
    default:
      return "/students/dashboard";
  }
}
